export const MIGRATION_V1_TABLE_STATEMENTS = [
    "CREATE TABLE \"schema_migrations\" (\n  \"version\" INTEGER NOT NULL,\n  \"migration_id\" TEXT NOT NULL,\n  \"applied_at\" TEXT NOT NULL,\n  \"checksum\" TEXT NOT NULL,\n  PRIMARY KEY (\"version\"),\n  CHECK (version >= 1),\n  CHECK (length(checksum) = 64)\n) STRICT;",
    "CREATE TABLE \"command_envelopes\" (\n  \"envelope_id\" TEXT NOT NULL,\n  \"idempotency_key\" TEXT NOT NULL,\n  \"input_digest\" TEXT NOT NULL,\n  \"source_message_id\" TEXT NOT NULL,\n  \"conversation_id\" TEXT NOT NULL,\n  \"state\" TEXT NOT NULL,\n  \"result_status\" TEXT NOT NULL,\n  \"received_at\" TEXT NOT NULL,\n  \"committed_at\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"envelope_id\"),\n  CHECK (length(input_digest) = 64),\n  CHECK (json_valid(payload_json)),\n  CHECK (state IN ('received','facts_committed','effects_pending','effects_stable','finalized'))\n) STRICT;",
    "CREATE TABLE \"idempotency_records\" (\n  \"idempotency_key\" TEXT NOT NULL,\n  \"operation_id\" TEXT NOT NULL,\n  \"input_digest\" TEXT NOT NULL,\n  \"state\" TEXT NOT NULL,\n  \"terminal_result_json\" TEXT,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  PRIMARY KEY (\"idempotency_key\"),\n  CHECK (length(input_digest) = 64),\n  CHECK (terminal_result_json IS NULL OR json_valid(terminal_result_json))\n) STRICT;",
    "CREATE TABLE \"event_records\" (\n  \"event_id\" TEXT NOT NULL,\n  \"envelope_id\" TEXT NOT NULL,\n  \"operation_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"event_type\" TEXT NOT NULL,\n  \"fact_kind\" TEXT NOT NULL,\n  \"source_message_id\" TEXT NOT NULL,\n  \"conversation_id\" TEXT NOT NULL,\n  \"received_at\" TEXT NOT NULL,\n  \"committed_at\" TEXT NOT NULL,\n  \"occurred_at_text\" TEXT,\n  \"result_status\" TEXT NOT NULL,\n  \"lifecycle_status\" TEXT NOT NULL,\n  \"meal_id\" TEXT,\n  \"meal_slot\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"event_id\"),\n  CHECK (json_valid(payload_json)),\n  CHECK (event_type <> 'diet_meal' OR (meal_id IS NOT NULL AND meal_slot IS NOT NULL)),\n  FOREIGN KEY (\"envelope_id\") REFERENCES \"command_envelopes\"(\"envelope_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"meal_items\" (\n  \"item_id\" TEXT NOT NULL,\n  \"event_id\" TEXT NOT NULL,\n  \"item_order\" INTEGER NOT NULL,\n  \"item_type\" TEXT NOT NULL,\n  \"normalized_name\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"item_id\"),\n  CHECK (item_order >= 0),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"event_id\") REFERENCES \"event_records\"(\"event_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"products\" (\n  \"product_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"normalized_name\" TEXT NOT NULL,\n  \"product_type\" TEXT NOT NULL,\n  \"brand\" TEXT,\n  \"manufacturer\" TEXT,\n  \"barcode\" TEXT,\n  \"sku\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"product_id\"),\n  CHECK (json_valid(payload_json))\n) STRICT;",
    "CREATE TABLE \"inventory_batches\" (\n  \"batch_id\" TEXT NOT NULL,\n  \"product_id\" TEXT NOT NULL,\n  \"stock_event_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"committed_at\" TEXT NOT NULL,\n  \"stocked_at\" TEXT NOT NULL,\n  \"explicit_expiration_at\" TEXT,\n  \"quantity_unit\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"batch_id\"),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\"(\"product_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"stock_event_id\") REFERENCES \"event_records\"(\"event_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"inventory_batch_projections\" (\n  \"batch_id\" TEXT NOT NULL,\n  \"last_event_id\" TEXT NOT NULL,\n  \"last_changed_at\" TEXT NOT NULL,\n  \"last_verified_at\" TEXT,\n  \"quantity_status\" TEXT NOT NULL,\n  \"seal_status\" TEXT NOT NULL,\n  \"expiry_status\" TEXT NOT NULL,\n  \"effective_status\" TEXT NOT NULL,\n  \"effective_expiration_at\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"batch_id\"),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"batch_id\") REFERENCES \"inventory_batches\"(\"batch_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"last_event_id\") REFERENCES \"event_records\"(\"event_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"inventory_transactions\" (\n  \"transaction_id\" TEXT NOT NULL,\n  \"event_id\" TEXT NOT NULL,\n  \"product_id\" TEXT NOT NULL,\n  \"batch_id\" TEXT NOT NULL,\n  \"idempotency_key\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"direction\" TEXT NOT NULL,\n  \"reason_code\" TEXT NOT NULL,\n  \"unit\" TEXT NOT NULL,\n  \"related_event_id\" TEXT,\n  \"related_transaction_id\" TEXT,\n  \"source_message_id\" TEXT NOT NULL,\n  \"conversation_id\" TEXT NOT NULL,\n  \"received_at\" TEXT NOT NULL,\n  \"committed_at\" TEXT NOT NULL,\n  \"result_status\" TEXT NOT NULL,\n  \"lifecycle_status\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"transaction_id\"),\n  CHECK (direction IN ('in','out','neutral')),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"event_id\") REFERENCES \"event_records\"(\"event_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"product_id\") REFERENCES \"products\"(\"product_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"batch_id\") REFERENCES \"inventory_batches\"(\"batch_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"nutrition_profiles\" (\n  \"nutrition_profile_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"subject_type\" TEXT NOT NULL,\n  \"subject_id\" TEXT NOT NULL,\n  \"profile_version\" TEXT NOT NULL,\n  \"source_type\" TEXT NOT NULL,\n  \"source_ref\" TEXT NOT NULL,\n  \"source_version\" TEXT NOT NULL,\n  \"retrieved_at\" TEXT NOT NULL,\n  \"coverage_status\" TEXT NOT NULL,\n  \"created_at\" TEXT NOT NULL,\n  \"supersedes_profile_id\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"nutrition_profile_id\"),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"supersedes_profile_id\") REFERENCES \"nutrition_profiles\"(\"nutrition_profile_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"nutrition_snapshots\" (\n  \"snapshot_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"meal_event_id\" TEXT NOT NULL,\n  \"intake_item_id\" TEXT NOT NULL,\n  \"nutrition_profile_id\" TEXT NOT NULL,\n  \"profile_version\" TEXT NOT NULL,\n  \"source_type\" TEXT NOT NULL,\n  \"source_ref\" TEXT NOT NULL,\n  \"coverage_status\" TEXT NOT NULL,\n  \"created_at\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"snapshot_id\"),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"meal_event_id\") REFERENCES \"event_records\"(\"event_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"intake_item_id\") REFERENCES \"meal_items\"(\"item_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"nutrition_profile_id\") REFERENCES \"nutrition_profiles\"(\"nutrition_profile_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"goal_versions\" (\n  \"goal_version_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"user_id\" TEXT NOT NULL,\n  \"timezone\" TEXT NOT NULL,\n  \"effective_from\" TEXT NOT NULL,\n  \"effective_to\" TEXT,\n  \"created_at\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"goal_version_id\"),\n  CHECK (effective_to IS NULL OR effective_to > effective_from),\n  CHECK (json_valid(payload_json))\n) STRICT;",
    "CREATE TABLE \"user_profiles\" (\n  \"profile_id\" TEXT NOT NULL,\n  \"user_id\" TEXT NOT NULL,\n  \"schema_version\" TEXT NOT NULL,\n  \"height_cm\" REAL NOT NULL,\n  \"weight_kg\" REAL NOT NULL,\n  \"sex\" TEXT,\n  \"age\" INTEGER,\n  \"goal_state\" TEXT,\n  \"effective_from\" TEXT NOT NULL,\n  \"effective_to\" TEXT,\n  \"created_at\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"profile_id\"),\n  CHECK (height_cm > 0),\n  CHECK (weight_kg > 0),\n  CHECK (age IS NULL OR age > 0),\n  CHECK (sex IS NULL OR sex IN ('male','female')),\n  CHECK (goal_state IS NULL OR goal_state IN ('cut','maintain','bulk')),\n  CHECK (effective_to IS NULL OR effective_to > effective_from),\n  CHECK (json_valid(payload_json))\n) STRICT;",
    "CREATE TABLE \"daily_progress_snapshots\" (\n  \"progress_snapshot_id\" TEXT NOT NULL,\n  \"idempotency_result_id\" TEXT,\n  \"date\" TEXT NOT NULL,\n  \"timezone\" TEXT NOT NULL,\n  \"goal_version_id\" TEXT,\n  \"coverage_status\" TEXT NOT NULL,\n  \"generated_at\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"progress_snapshot_id\"),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"goal_version_id\") REFERENCES \"goal_versions\"(\"goal_version_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"idempotency_result_id\") REFERENCES \"idempotency_records\"(\"idempotency_key\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"issues\" (\n  \"issue_id\" TEXT NOT NULL,\n  \"issue_code\" TEXT NOT NULL,\n  \"issue_type\" TEXT NOT NULL,\n  \"priority\" TEXT NOT NULL,\n  \"entity_type\" TEXT NOT NULL,\n  \"entity_id\" TEXT,\n  \"field_path\" TEXT,\n  \"detected_at\" TEXT NOT NULL,\n  \"source_message_id\" TEXT,\n  \"status\" TEXT NOT NULL,\n  \"revision\" INTEGER NOT NULL,\n  \"last_presented_at\" TEXT,\n  \"resolved_at\" TEXT,\n  \"resolution_source\" TEXT,\n  \"resolution_reason\" TEXT,\n  \"resolution_event_id\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"issue_id\"),\n  CHECK (revision >= 1),\n  CHECK (status IN ('open','awaiting_user','resolved','dismissed')),\n  CHECK (json_valid(payload_json))\n) STRICT;",
    "CREATE TABLE \"issue_resolution_events\" (\n  \"event_id\" TEXT NOT NULL,\n  \"issue_id\" TEXT NOT NULL,\n  \"request_id\" TEXT NOT NULL,\n  \"expected_revision\" INTEGER NOT NULL,\n  \"application_outcome\" TEXT NOT NULL,\n  \"resolution_reason\" TEXT,\n  \"rejection_reason\" TEXT,\n  \"resolution_source\" TEXT,\n  \"created_at\" TEXT NOT NULL,\n  PRIMARY KEY (\"event_id\"),\n  CHECK (expected_revision >= 1),\n  FOREIGN KEY (\"issue_id\") REFERENCES \"issues\"(\"issue_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"correction_events\" (\n  \"correction_id\" TEXT NOT NULL,\n  \"target_event_id\" TEXT NOT NULL,\n  \"base_revision\" INTEGER NOT NULL,\n  \"request_id\" TEXT NOT NULL,\n  \"operation\" TEXT NOT NULL,\n  \"created_at\" TEXT NOT NULL,\n  \"timezone\" TEXT NOT NULL,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"correction_id\"),\n  CHECK (base_revision >= 1),\n  CHECK (operation IN ('change_amount','change_unit','change_time','change_meal_slot','change_item_name','change_food_type','change_components','add_item','remove_item','change_inventory_link','change_nutrition_source','void_event','restore_event')),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"target_event_id\") REFERENCES \"event_records\"(\"event_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"effect_outbox\" (\n  \"outbox_id\" TEXT NOT NULL,\n  \"envelope_id\" TEXT NOT NULL,\n  \"operation_id\" TEXT NOT NULL,\n  \"effect_id\" TEXT NOT NULL,\n  \"effect_kind\" TEXT NOT NULL,\n  \"previous_state\" TEXT,\n  \"state\" TEXT NOT NULL,\n  \"attempt_count\" INTEGER NOT NULL DEFAULT 0,\n  \"reason\" TEXT,\n  \"created_at\" TEXT NOT NULL,\n  \"updated_at\" TEXT NOT NULL,\n  PRIMARY KEY (\"outbox_id\"),\n  CHECK (attempt_count >= 0),\n  CHECK (state IN ('pending','processing','succeeded','retryable_failed','permanent_business_skip')),\n  FOREIGN KEY (\"envelope_id\") REFERENCES \"command_envelopes\"(\"envelope_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"effect_bundle_commits\" (\n  \"envelope_id\" TEXT NOT NULL,\n  \"operation_id\" TEXT NOT NULL,\n  \"stage\" TEXT NOT NULL,\n  \"effect_state\" TEXT NOT NULL,\n  \"result_status\" TEXT NOT NULL,\n  \"completed_at\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"envelope_id\", \"operation_id\"),\n  CHECK (stage = 'EffectBundle'),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"envelope_id\") REFERENCES \"command_envelopes\"(\"envelope_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"envelope_finalizations\" (\n  \"envelope_id\" TEXT NOT NULL,\n  \"idempotency_key\" TEXT NOT NULL,\n  \"input_digest\" TEXT NOT NULL,\n  \"envelope_state\" TEXT NOT NULL,\n  \"result_status\" TEXT NOT NULL,\n  \"stage\" TEXT NOT NULL,\n  \"receipt_id\" TEXT,\n  \"error_code\" TEXT,\n  \"finalized_at\" TEXT,\n  \"frozen_at\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"envelope_id\"),\n  CHECK (length(input_digest) = 64),\n  CHECK (stage = 'EnvelopeFinalize'),\n  CHECK (json_valid(payload_json)),\n  CHECK ((result_status IN ('committed','committed_with_issues') AND finalized_at IS NOT NULL AND receipt_id IS NOT NULL AND error_code IS NULL) OR (result_status = 'failed' AND finalized_at IS NULL AND receipt_id IS NULL AND error_code IS NOT NULL)),\n  CHECK (json_type(payload_json, '$.items') IS NULL OR frozen_at IS NOT NULL),\n  FOREIGN KEY (\"envelope_id\") REFERENCES \"command_envelopes\"(\"envelope_id\") ON UPDATE RESTRICT ON DELETE RESTRICT,\n  FOREIGN KEY (\"idempotency_key\") REFERENCES \"idempotency_records\"(\"idempotency_key\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;",
    "CREATE TABLE \"mixed_item_results\" (\n  \"envelope_id\" TEXT NOT NULL,\n  \"sequence\" INTEGER NOT NULL,\n  \"operation_id\" TEXT NOT NULL,\n  \"idempotency_key\" TEXT NOT NULL,\n  \"command_type\" TEXT NOT NULL,\n  \"status\" TEXT NOT NULL,\n  \"error_code\" TEXT,\n  \"payload_json\" TEXT NOT NULL,\n  PRIMARY KEY (\"envelope_id\", \"sequence\"),\n  CHECK (sequence >= 0),\n  CHECK (json_valid(payload_json)),\n  FOREIGN KEY (\"envelope_id\") REFERENCES \"envelope_finalizations\"(\"envelope_id\") ON UPDATE RESTRICT ON DELETE RESTRICT\n) STRICT;"
];
